/**
 * A2A skill extraction: one `elementum_agent_a2a_skill` block → its
 * normalized shape. Pure metadata (no target/field refs, no `app_id` on
 * the wire — see `provider/docs/resources/agent_a2a_skill.md`), so this is
 * the simplest owned-child extractor in the agent family.
 */
import { EntityTfError } from "../../engine/entity.js";
import { optionalString, resourceRefLabel } from "../../engine/pull/context.js";
import { AGENT_A2A_SKILL_RESOURCE_TYPE } from "./module.js";
const KNOWN_A2A_SKILL_ATTRS = new Set(["agent_id", "name", "description", "tags", "examples", "input_modes", "output_modes"]);
function optionalStringArray(attrs, key, where, ctx) {
    const v = attrs[key];
    if (v === undefined)
        return undefined;
    if (!Array.isArray(v) || !v.every((item) => typeof item === "string")) {
        ctx.diagnostics.push(`${where}: expected a list of strings "${key}", got ${JSON.stringify(v)}; dropped`);
        return undefined;
    }
    return [...v].sort();
}
/** One a2a-skill block → its normalized shape; undefined = skipped with a diagnostic (wrong owner, missing required attr). */
export function a2aSkillFromTf(block, owner, ctx) {
    if (block.type !== AGENT_A2A_SKILL_RESOURCE_TYPE) {
        ctx.diagnostics.push(`resource "${block.type}" is not a known a2a skill resource; skipped`);
        return undefined;
    }
    const label = block.label;
    if (label === undefined || label === "") {
        throw new EntityTfError(`${block.type} block is missing its label`);
    }
    const attrs = block.attrs;
    const name = optionalString(attrs, "name", `a2a skill (${block.type}.${label})`, ctx) ?? "";
    const where = `a2a skill "${name}" (${block.type}.${label})`;
    for (const key of Object.keys(attrs)) {
        if (!KNOWN_A2A_SKILL_ATTRS.has(key)) {
            ctx.diagnostics.push(`${where}: unhandled attribute "${key}" — the export dialect grew; extend a2aSkillFromTf deliberately`);
        }
    }
    if (resourceRefLabel(attrs["agent_id"], owner.agentType) !== owner.agentLabel) {
        ctx.diagnostics.push(`${where}: agent_id does not reference ${owner.agentType}.${owner.agentLabel}; skipped`);
        return undefined;
    }
    if (name === "") {
        ctx.diagnostics.push(`${where}: name is required; skipped`);
        return undefined;
    }
    const description = optionalString(attrs, "description", where, ctx);
    if (description === undefined || description === "") {
        ctx.diagnostics.push(`${where}: description is required; skipped`);
        return undefined;
    }
    const tags = optionalStringArray(attrs, "tags", where, ctx);
    const examples = optionalStringArray(attrs, "examples", where, ctx);
    const inputModes = optionalStringArray(attrs, "input_modes", where, ctx);
    const outputModes = optionalStringArray(attrs, "output_modes", where, ctx);
    return {
        name,
        description,
        ...(tags !== undefined && tags.length > 0 && { tags }),
        ...(examples !== undefined && examples.length > 0 && { examples }),
        ...(inputModes !== undefined && inputModes.length > 0 && { inputModes }),
        ...(outputModes !== undefined && outputModes.length > 0 && { outputModes }),
    };
}
